// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new PoCGame(address(this), 0); vm.stopPrank(); }
    function testFuzz_property(address tokenAddress, address tokenOwner, uint256 tokens, bool tokenSucceeds) public {
        vm.assume(tokenAddress != address(0));
        RecToken t = new RecToken();
        t.setOk(tokenSucceeds);
        tokenAddress = address(t);
        vm.prank(address(uint160(0xE0A)));
        bool ok;
        bool returned = false;
        try c.transferAnyERC20Token(tokenAddress, tokenOwner, tokens) returns (bool r) {
            ok = true;
            returned = r;
        } catch {
            ok = false;
        }
        // General rule: the call never completes successfully while reporting false —
        // either it reverts (failing token) or it succeeds and returns true.
        assertTrue(!ok || returned, "successful completion must not return false");
    }
}

contract RecToken {
    bool public ok;
    function setOk(bool o) external { ok = o; }
    function transfer(address, uint256) external returns (bool) {
        require(ok);
        return true;
    }
}
